package com.elitedarkkaiser.nubialy;
import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w440dp-h900dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SettingsEditorTest {
 @Test public void legacyLayoutMigratesWithoutChangingAppearance()throws Exception {var c=RuntimeEnvironment.getApplication();var old=SettingsStyle.DEFAULT.with(0,1).with(3,0xff123456).with(8,88);c.getSharedPreferences("settings_editor",0).edit().putString("draft",old.encode()).putString("active",old.encode()).putBoolean("enabled",true).commit();assertEquals(old.with(0,0),SettingsPreferences.draft(c));assertEquals(old.with(0,0),SettingsPreferences.active(c));var ctl=Robolectric.buildActivity(SettingsEditorActivity.class).setup();assertNull(ctl.get().findViewById(android.R.id.content).findViewWithTag("settings-layout:1"));render(ctl.get().findViewById(android.R.id.content),"settings-native-controls");ctl.pause().stop().destroy();}
 @Test public void allSharedCardEffectsRespectCanvasAndRevocation(){for(int id:new int[]{0,1,2,3,4,5,6,7,101,102,103,104,105,201,202,203,204,205,206}){boolean[] allowed={true};var d=new SettingsCardDrawable(SettingsStyle.DEFAULT.with(12,id),1,()->allowed[0]);d.setBounds(10,10,150,90);Bitmap b=Bitmap.createBitmap(160,100,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);int saves=c.getSaveCount();d.draw(c);assertEquals(saves,c.getSaveCount());assertEquals(0,b.getPixel(0,0));allowed[0]=false;b.eraseColor(Color.TRANSPARENT);d.draw(c);int[] pixels=new int[16000];b.getPixels(pixels,0,160,0,0,160,100);assertTrue(java.util.Arrays.stream(pixels).allMatch(v->v==0));b.recycle();}}
 @Test public void restoreStopsOnlySettingsProfile(){var c=RuntimeEnvironment.getApplication();var s=SettingsStyle.DEFAULT;assertTrue(SettingsPreferences.save(c,s));assertNull(SettingsPreferences.active(c));assertTrue(SettingsPreferences.activate(c,s));assertEquals(s,SettingsPreferences.active(c));assertTrue(SettingsPreferences.stop(c));assertNull(SettingsPreferences.active(c));assertEquals(s,SettingsPreferences.draft(c));}
 private void render(View root,String name)throws Exception {root.measure(View.MeasureSpec.makeMeasureSpec(440,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(900,View.MeasureSpec.EXACTLY));root.layout(0,0,440,900);Bitmap b=Bitmap.createBitmap(440,900,Bitmap.Config.ARGB_8888);root.draw(new Canvas(b));File f=new File("build/editor-previews/"+name+".png");f.getParentFile().mkdirs();try(var out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
}
